Create Procedure PedPen as SELECT ID,ORDER_DATE,CUSTOMER_ID,CUSTOMER_NAME,VAT_REGISTRATION,CURRENCY_ID,AMOUNT from [IVM].dbo.ORDERS WHERE STATUS='V'  and CUSTOMER_ID>='100' and CUSTOMER_ID<='20549177248' and CADUCATE_DATE>='01-10-2013' and CADUCATE_DATE<='05-10-2013' and STATUS_ORDER='AUTORIZADO' order by CUSTOMER_ID